const surveyNumericResults = `-- name: SurveyNumericResults :many
SELECT q.id AS question_id, q.kind,
  count(a.id)::int AS answers,
  coalesce(sum(a.value_num), 0)::bigint AS total,
  count(a.id) FILTER (WHERE q.kind = 'nps' AND a.value_num >= 9)::int AS promoters,
  count(a.id) FILTER (WHERE q.kind = 'nps' AND a.value_num BETWEEN 7 AND 8)::int AS passives,
  count(a.id) FILTER (WHERE q.kind = 'nps' AND a.value_num <= 6)::int AS detractors
FROM survey_question q
LEFT JOIN survey_answer a ON a.workspace_id = q.workspace_id AND a.question_id = q.id AND a.value_num IS NOT NULL
  AND EXISTS (SELECT 1 FROM survey_response r WHERE r.workspace_id = a.workspace_id AND r.id = a.response_id AND r.state = 'complete')
WHERE q.workspace_id = $1 AND q.survey_id = $2 AND q.kind IN ('nps', 'csat')
GROUP BY q.id, q.kind, q.ordinal ORDER BY q.ordinal
`

type SurveyNumericResultsParams struct {
	WorkspaceID uuid.UUID
	SurveyID    uuid.UUID
}

type SurveyNumericResultsRow struct {
	QuestionID uuid.UUID
	Kind       string
	Answers    int32
	Total      int64
	Promoters  int32
	Passives   int32
	Detractors int32
}

func (q *Queries) SurveyNumericResults(ctx context.Context, arg SurveyNumericResultsParams) ([]SurveyNumericResultsRow, error) {
	rows, err := q.db.Query(ctx, surveyNumericResults, arg.WorkspaceID, arg.SurveyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SurveyNumericResultsRow
	for rows.Next() {
		var i SurveyNumericResultsRow
		if err := rows.Scan(
			&i.QuestionID,
			&i.Kind,
			&i.Answers,
			&i.Total,
			&i.Promoters,
			&i.Passives,
			&i.Detractors,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const toggleSurveyInvite = `-- name: ToggleSurveyInvite :execrows
UPDATE survey_invite SET state = CASE WHEN $3::boolean THEN 'excluded' ELSE 'draft' END, updated_at = now()
WHERE workspace_id = $1 AND id = $2 AND state = CASE WHEN $3::boolean THEN 'draft' ELSE 'excluded' END
`

type ToggleSurveyInviteParams struct {
	WorkspaceID uuid.UUID
	ID          uuid.UUID
	Exclude     bool
}

func (q *Queries) ToggleSurveyInvite(ctx context.Context, arg ToggleSurveyInviteParams) (int64, error) {
	result, err := q.db.Exec(ctx, toggleSurveyInvite, arg.WorkspaceID, arg.ID, arg.Exclude)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateSurveyBasics = `-- name: UpdateSurveyBasics :execrows
UPDATE survey SET title = $3, intro = $4, thank_you = $5, delivery = $6, on_person_delete = $7, updated_at = now()
WHERE workspace_id = $1 AND id = $2
`

type UpdateSurveyBasicsParams struct {
	WorkspaceID    uuid.UUID
	ID             uuid.UUID
	Title          string
	Intro          string
	ThankYou       string
	Delivery       string
	OnPersonDelete string
}

func (q *Queries) UpdateSurveyBasics(ctx context.Context, arg UpdateSurveyBasicsParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateSurveyBasics,
		arg.WorkspaceID,
		arg.ID,
		arg.Title,
		arg.Intro,
		arg.ThankYou,
		arg.Delivery,
		arg.OnPersonDelete,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const upsertSurveyAnswer = `-- name: UpsertSurveyAnswer :exec
INSERT INTO survey_answer (workspace_id, response_id, question_id, value_num, value_choice, value_text)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (response_id, question_id) DO UPDATE SET value_num = EXCLUDED.value_num, value_choice = EXCLUDED.value_choice, value_text = EXCLUDED.value_text
`

type UpsertSurveyAnswerParams struct {
	WorkspaceID uuid.UUID
	ResponseID  uuid.UUID
	QuestionID  uuid.UUID
	ValueNum    pgtype.Int4
	ValueChoice pgtype.Text
	ValueText   pgtype.Text
}

func (q *Queries) UpsertSurveyAnswer(ctx context.Context, arg UpsertSurveyAnswerParams) error {
	_, err := q.db.Exec(ctx, upsertSurveyAnswer,
		arg.WorkspaceID,
		arg.ResponseID,
		arg.QuestionID,
		arg.ValueNum,
		arg.ValueChoice,
		arg.ValueText,
	)
	return err
}
